// Logo de Veterinaria Sonrisas en base64 para los documentos descargados (PDF y Excel).
// Con file:// el navegador no deja leer pictures/logo.png con fetch ni con <img> + canvas,
// por eso el logo viaja dentro de este script.
//
// CÓMO REGENERARLO si cambia el logo (PowerShell, desde la carpeta FRONTEND):
//   Add-Type -AssemblyName System.Drawing
//   $img = [System.Drawing.Image]::FromFile("$PWD\pictures\logo.png")
//   $h = [int]($img.Height * 256 / $img.Width)
//   $bmp = New-Object System.Drawing.Bitmap 256, $h
//   $g = [System.Drawing.Graphics]::FromImage($bmp)
//   $g.InterpolationMode = 'HighQualityBicubic'; $g.DrawImage($img, 0, 0, 256, $h)
//   $ms = New-Object System.IO.MemoryStream; $bmp.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)
//   [Convert]::ToBase64String($ms.ToArray())
// Copia el resultado en `base64` (después de 'data:image/png;base64,') y actualiza `alto`
// con el valor de $h.
// Se reduce a 256 px de ancho para que cada PDF no pese de más; se ve nítido impreso a 2 cm.
window.MARCA_LOGO = {
    ancho: 256,
    alto: 268,
    base64: 'data:image/png;base64,',
};